mapper.select:
/** pdaSql - selectProjectEmpList - 참여연구원 기여율 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" , A.VPROJECTCODE as "vProjectCode" , A.VEMPLNO as "vEmplNo" , B.VNAME as "vName" , C.VTEAMNAME as "vDeptName" , D.VTEAMNAME as "vTeamName" , E.VPOSNAME as "vPosName" , A.NCONTRIBUTION as "nContribution" , A.VCONTENT as "vContent" , A.VCONFIRM as "vConfirm" , A.VFINISH as "vFinish" FROM TCA4005 A, TCA4002 F, TAA2101 B, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG IN ('1', '2')) C, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG = '3' ORDER BY VHIGHTEAM, VTEAMCODE) D, (SELECT VPOSCODE, VPOSNAME, VGRADENAME FROM TAZ2003) E
A.VESTICODE = #{vEstiCode} AND A.VPROJECTCODE = #{vProjectCode} AND A.VESTICODE = F.VESTICODE AND A.VEMPLNO = F.VEMPLNO AND F.VESTIYN = 'Y' AND A.VEMPLNO = B.VEMPLNO AND B.VDEPTCODE = C.VTEAMCODE(+) AND B.VTEAMCODE = D.VTEAMCODE(+) AND B.VPOSCODE = E.VPOSCODE(+)
ORDER BY B.VDEPTCODE, B.VTEAMCODE, B.VPOSCODE, B.NESTIPOINT DESC

/** pdaSql - selectReview - 평가의견 조회 */
SELECT
   VREVIEWCONTENT   as "vReviewContent"
FROM
   TCA4006

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND NSEQNO = (
                 SELECT
                    MAX(NSEQNO)
                 FROM
                    TCA4006
                 WHERE
                        VESTICODE = #{vEstiCode}
                    AND VPROJECTCODE = #{vProjectCode}
              )

mapper.insert:
      /** pdaSql - insertReview - 평가의견 저장 */
      
         SELECT
            NVL(MAX(NSEQNO), 0) + 1   as "nSeqNo"
         FROM
            TCA4006
         
                VESTICODE = #{vEstiCode}
            AND VPROJECTCODE = #{vProjectCode}
         
      

      INSERT INTO
         TCA4006
         (
              VESTICODE
            , VPROJECTCODE
            , NSEQNO
            , VREVIEWCONTENT
         )
      VALUES
         (
              #{vEstiCode}
            , #{vProjectCode}
            , #{nSeqNo}
            , #{vReviewContent}
         )

mapper.update:
/** pdaSql - updateEstiStep3 - 평가자가 반려 */
UPDATE TCA4003
   SET
      VESTISTEP = '3'

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VPROJECTEVA = #{vProjectEva}

/** pdaSql - updateEstiStep4 - 평가자가 완료(승인) */
UPDATE TCA4003
   SET
      VESTISTEP = '4'

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VPROJECTEVA = #{vProjectEva}
